    private TravelZoneUi.Catalog zoneCatalog;private int zoneLimit=60;
    private String cueParent="",renderedRoute="";private final Map<String,Integer> scrolls=new HashMap<>();
    private TravelCuePlan cues;private String cueBefore="",cueError="",pickerKind="reminder";private android.window.OnBackInvokedCallback backCallback;private TravelPlan draft;private TravelPlans.Repository repository;private String route="",query="",error="",token,job="";private YearMonth month;
    private boolean resumed,permissionSave;private Dialog dialog;private Bundle picker;private TravelClock homeDial,targetDial;private TextView homeTime,targetTime,homeDate,targetDate,homeOffset,targetOffset,difference,differenceDirection,departureDifference,problem;private LinearLayout body;
