    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);repository=TravelPlans.repository(this);try{draft=repository.load(TravelReminders.clock.getAsLong());cues=new TravelCueStore(repository.prefs).load(draft,TravelReminders.clock.getAsLong());if(state!=null){cueParent=state.getString("cueParent","");Bundle positions=state.getBundle("routeScrolls");if(positions!=null)for(String key:positions.keySet())scrolls.put(key,positions.getInt(key));draft.home=state.getString("home",draft.home);draft.destination=state.getString("destination",draft.destination);draft.departure=LocalDate.parse(state.getString("departure",draft.departure.toString()));draft.minute=state.getInt("minute",draft.minute);draft.days=state.getInt("days",draft.days);draft.reminders=state.getBoolean("reminders",draft.reminders);draft.trackingReminders=state.getBoolean("trackingReminders",draft.trackingReminders);draft.revision=state.getLong("revision",draft.revision);route=state.getString("route","");query=state.getString("query","");zoneLimit=Math.max(60,state.getInt("zoneLimit",60));error=state.getString("error","");token=state.getString("token");job=state.getString("job","");picker=state.getBundle("picker");pickerKind=state.getString("pickerKind","reminder");permissionSave=state.getBoolean("permissionSave");cueBefore=state.getString("cueBefore","");cueError=state.getString("cueError","");if(state.containsKey("cues"))cues=TravelCueJson.decode(new org.json.JSONObject(state.getString("cues")));}if(Build.VERSION.SDK_INT>=33){backCallback=this::back;getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,backCallback);}month=state==null?YearMonth.from(draft.departure):YearMonth.parse(state.getString("month",YearMonth.from(draft.departure).toString()));render();if(state==null&&draft.revision>0){job="reconcile";token=UUID.randomUUID().toString();render();}}catch(Exception failure){unavailable(failure);}}
    @Override protected void onResume(){super.onResume();resumed=true;handler.post(tick);observe();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(tick);handler.removeCallbacks(poll);super.onPause();}
    private void unavailable(Exception failure){draft=null;token=null;body=Design.page(this,false,null,n->{});RecordUi.header(body,"Travel mode",this::finish);Design.text(body,failure.getMessage()==null?"Your travel plan could not be read.":failure.getMessage(),15,400,Design.MUTED);Design.button(body,"Try again",true,this::recreate);}
    private void render(){
        rememberScroll();homeDial=targetDial=null;problem=null;
        switch(route){
            case "date":case "cue-date":calendar();break;
            case "cues":cueSettings();break;
            case "light":lightSettings();break;
            case "planning":planningSettings();break;
            case "tracking":trackingSettings();break;
            case "reminders":reminderSettings();break;
            case "home":case "destination":zones();break;
            default:route="";mainPage();
        }
        // Let long zone names, errors and larger text grow within this feature's scroll view.
        body.setLayoutParams(new ScrollView.LayoutParams(-1,-2));
        renderedRoute=route;
        if(body.getParent() instanceof ScrollView scroll){int position=scrolls.getOrDefault(route,0);scroll.post(()->scroll.scrollTo(0,position));}
        clocks();restorePicker();
    }
    private void rememberScroll(){if(body!=null&&body.getParent() instanceof ScrollView scroll)scrolls.put(renderedRoute,scroll.getScrollY());}
    private void go(String destination){route=destination;render();}
