    private void clocks(){if(homeDial==null||targetDial==null||draft==null||!route.isEmpty())return;long now=TravelReminders.clock.getAsLong();homeDial.update(now);targetDial.update(now);DateTimeFormatter dateFormat=DateTimeFormatter.ofPattern("EEE d MMM",Locale.getDefault());homeDate.setText(Instant.ofEpochMilli(now).atZone(ZoneId.of(draft.home)).format(dateFormat));targetDate.setText(Instant.ofEpochMilli(now).atZone(ZoneId.of(draft.destination)).format(dateFormat));homeOffset.setText(TravelPlan.offset(draft.home,now));targetOffset.setText(TravelPlan.offset(draft.destination,now));homeTime.setText(RecordUi.clock(this,now,ZoneId.of(draft.home)));targetTime.setText(RecordUi.clock(this,now,ZoneId.of(draft.destination)));int shift=draft.differenceSeconds(now),departureShift=draft.differenceSeconds(draft.departureAnchor());String shiftDescription=TravelPlan.difference(shift);difference.setText(RecordUi.units(shift==0?"0 h":shiftDescription.replace(" ahead","").replace(" behind","")));difference.setContentDescription("Destination time: "+shiftDescription);differenceDirection.setText(shift==0?"Same time":shift>0?"Target ahead":"Target behind");departureDifference.setText("On departure day: "+TravelPlan.difference(departureShift));departureDifference.setVisibility(departureShift==shift?View.GONE:View.VISIBLE);homeTime.setContentDescription("Home clock "+RecordUi.date(now,ZoneId.of(draft.home))+" "+homeTime.getText());targetTime.setContentDescription("Destination clock "+RecordUi.date(now,ZoneId.of(draft.destination))+" "+targetTime.getText());}
    private void zoneRoute(String route){this.route=route;query="";zoneLimit=60;render();}
    private void zones(){body=Design.page(this,false,null,n->{});RecordUi.header(body,route.equals("home")?"Home time zone":"Target time zone",this::back);EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(16*Appearance.scale(this));search.setTypeface(Design.font(this,400));search.setTextColor(Design.INK);search.setHint("Search city, country or region");search.setHintTextColor(Design.MUTED);search.setCompoundDrawables(RecordUi.glyph(this,"search",Design.MUTED,20),null,null,null);search.setCompoundDrawablePadding(Design.dp(this,10));search.setContentDescription("Search time zones");Design.pad(search,14,12);search.setBackground(Design.shape(this,Design.SOFT,14));body.addView(search,new LinearLayout.LayoutParams(-1,-2));Design.space(body,8);LinearLayout results=Design.col(this);body.addView(results);search.setText(query);fillZones(results);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();zoneLimit=60;fillZones(results);}public void afterTextChanged(Editable e){}});}
    private TravelZoneUi.Catalog zoneCatalog(){if(zoneCatalog==null)zoneCatalog=new TravelZoneUi.Catalog(getResources().getConfiguration().getLocales().get(0));return zoneCatalog;}
    private void fillZones(LinearLayout results){
        results.removeAllViews();String current=route.equals("home")?draft.home:draft.destination;List<TravelZoneUi.Entry> matches=zoneCatalog().matches(query,current);
        if(matches.isEmpty()){Design.space(results,16);Design.text(results,"No matching city or time zone.",15,500,Design.INK);Design.space(results,6);Design.text(results,"Try a country, region or another city name.",13,400,Design.MUTED);return;}
        boolean blank=query.trim().isEmpty();int shown=Math.min(zoneLimit,matches.size());long now=TravelReminders.clock.getAsLong();
        for(int index=0;index<shown;index++){
            TravelZoneUi.Entry entry=matches.get(index);String zone=entry.id;boolean selected=zone.equals(current);
            if(blank&&index==0&&selected){Design.space(results,8);Design.text(results,"Selected time zone",12,600,Design.MUTED);Design.space(results,4);}
            else if(blank&&index==1&&matches.get(0).id.equals(current)){Design.space(results,16);Design.text(results,"All cities",12,600,Design.MUTED);Design.space(results,4);}
            LinearLayout row=Design.row(this);Design.pad(row,10,12);row.setMinimumHeight(Design.dp(this,68));row.setBackground(Design.touch(this,selected?Design.SOFT:Color.TRANSPARENT,14));
            row.addView(new SleepPicker.Mark(this,selected),new LinearLayout.LayoutParams(Design.dp(this,24),Design.dp(this,24)));LinearLayout copy=Design.col(this);copy.setPadding(Design.dp(this,12),0,0,0);Design.text(copy,entry.city,16,selected?600:500,Design.INK);Design.space(copy,4);Design.text(copy,entry.place()+" · "+TravelPlan.offset(zone,now),12,400,Design.MUTED);if(zoneCatalog().needsId(entry)){Design.space(copy,3);Design.text(copy,zone,11,400,Design.MUTED);}row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));
            SleepPicker.radio(row,selected);row.setContentDescription("Use time zone "+zone);row.setStateDescription(entry.city+" · "+entry.place()+" · "+TravelPlan.offset(zone,now));row.setOnClickListener(view->{if(!selected)InteractionFeedback.selection(view);if(route.equals("home"))draft.home=zone;else draft.destination=zone;changedTrip();route="";render();});results.addView(row);
        }
        if(matches.size()>shown){Design.space(results,12);RecordUi.quietButton(results,"Show more cities",()->{zoneLimit=Math.min(matches.size(),zoneLimit+60);fillZones(results);});Design.text(results,"Showing "+shown+" of "+matches.size()+" · search to narrow the list",12,400,Design.MUTED);}
    }
    private void calendar(){body=Design.page(this,false,null,n->{});RecordUi.header(body,route.equals("cue-date")?"First cue night":"Departure date",this::back);Design.space(body,12);LinearLayout controls=Design.row(this);View previous=Design.iconButton(this,"back","Previous month",()->{month=month.minusMonths(1);render();}),next=Design.iconButton(this,"chevron","Next month",()->{month=month.plusMonths(1);render();});previous.setEnabled(month.isAfter(YearMonth.of(2000,1)));next.setEnabled(month.isBefore(YearMonth.of(2100,12)));controls.addView(previous,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));TextView title=Design.text(this,month.format(DateTimeFormatter.ofPattern("MMMM uuuu",Locale.getDefault())),20,600,Design.INK);title.setGravity(Gravity.CENTER);controls.addView(title,new LinearLayout.LayoutParams(0,-2,1));controls.addView(next,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(controls);Design.space(body,10);String[] weekdays={"M","T","W","T","F","S","S"};LinearLayout labels=Design.row(this);for(String label:weekdays){TextView value=Design.text(this,label,12,500,Design.MUTED);value.setGravity(Gravity.CENTER);labels.addView(value,new LinearLayout.LayoutParams(0,Design.dp(this,40),1));}body.addView(labels);int offset=month.atDay(1).getDayOfWeek().getValue()-1;for(int week=0;week<(offset+month.lengthOfMonth()+6)/7;week++){LinearLayout row=Design.row(this);for(int col=0;col<7;col++){int day=week*7+col-offset+1;if(day<1||day>month.lengthOfMonth()){row.addView(new View(this),new LinearLayout.LayoutParams(0,Design.dp(this,48),1));continue;}LocalDate date=month.atDay(day);TextView value=Design.text(this,""+day,16,500,date.equals(route.equals("cue-date")?cues.first:draft.departure)?Design.CREAM:Design.INK);value.setGravity(Gravity.CENTER);value.setBackground(Design.touch(this,date.equals(route.equals("cue-date")?cues.first:draft.departure)?Design.BROWN:Color.TRANSPARENT,24));value.setContentDescription((route.equals("cue-date")?"Cue date ":"Departure ")+date);value.setSelected(date.equals(route.equals("cue-date")?cues.first:draft.departure));value.setFocusable(true);value.setOnClickListener(v->{if(route.equals("cue-date")){cues=cues.change(false,false,date,cues.minute,cues.minutes,cues.nights);route="cues";}else{draft.departure=date;changedTrip();route="";}render();});row.addView(value,new LinearLayout.LayoutParams(0,Design.dp(this,48),1));}body.addView(row);}Design.space(body,16);Design.text(body,route.equals("cue-date")?"Cue windows use your saved home time zone.":"Reminders begin on this date in the destination time zone.",13,400,Design.MUTED);}
    private void restorePicker(){if(picker==null)return;Bundle restore=picker;picker=null;switch(pickerKind){case "about":aboutCues();break;case "cueTime":pickCueTime();break;case "cueLength":pickCueLength();break;case "cueNights":pickCueNights();break;case "reminderDays":pickDays();break;default:pickTime();}if(dialog!=null)dialog.onRestoreInstanceState(restore);}
    private void pickCueTime(){pickerKind="cueTime";open(()->SleepPicker.time(this,"Cue window start",cues.minute,n->{cues=cues.change(false,false,cues.first,n,cues.minutes,cues.nights);render();}));}
    private void pickCueLength(){pickerKind="cueLength";open(()->SleepPicker.choices(this,"Cue window length",new String[]{"15 min","30 min","60 min"},cues.minutes==15?0:cues.minutes==30?1:2,n->{cues=cues.change(false,false,cues.first,cues.minute,new int[]{15,30,60}[n],cues.nights);render();}));}
    private void pickCueNights(){pickerKind="cueNights";String[] labels=new String[14];for(int n=0;n<14;n++)labels[n]=(n+1)+(n==0?" night":" nights");open(()->SleepPicker.choices(this,"Cue nights",labels,cues.nights-1,n->{cues=cues.change(false,false,cues.first,cues.minute,cues.minutes,n+1);render();}));}
    private void pickTime(){pickerKind="reminder";open(()->SleepPicker.time(this,"Daylight reminder time",draft.minute,value->{draft.minute=value;render();}));}
    private void pickDays(){pickerKind="reminderDays";String[] labels=new String[14];for(int n=0;n<14;n++)labels[n]=(n+1)+(n==0?" day":" days");open(()->SleepPicker.choices(this,"Reminder days",labels,draft.days-1,n->{draft.days=n+1;render();}));}
    private void open(java.util.function.Supplier<Dialog> create){if(dialog!=null&&dialog.isShowing())return;dialog=create.get();}
    private void save(){if(token!=null)return;try{draft.validate();cues.validateTrip(draft);TravelTrackingReminders.validate(draft,cues,TravelReminders.clock.getAsLong());if(cues.enabled&&cues.next(TravelReminders.clock.getAsLong())==null)throw new IllegalArgumentException("These cue windows ended. Review another window or turn cues off.");if(draft.reminders&&draft.next(TravelReminders.clock.getAsLong(),0)==0)throw new IllegalArgumentException("These reminder days have passed. Choose a later date or turn reminders off.");if((draft.reminders||draft.trackingReminders)&&!TravelReminders.port.allowed(this)){notifications(true);return;}startJob("save");}catch(Exception failure){show(failure.getMessage());}}
    private void notifications(){notifications(false);}
    private void notifications(boolean saveAfter){permissionSave=saveAfter;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED&&(!repository.prefs.getBoolean("travelNotificationAsked",false)||shouldShowRequestPermissionRationale(Manifest.permission.POST_NOTIFICATIONS))){repository.prefs.edit().putBoolean("travelNotificationAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},81);}else{permissionSave=false;show("Allow Travel reminders in Android notification settings.");startActivity(new Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()));}}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==81){boolean continueSave=permissionSave;permissionSave=false;if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED){if(continueSave)save();else render();}else show("Notifications were not allowed. Turn reminders off to save a clock-only plan, or allow them in Android app settings.");}}
    private void startJob(String kind){if(token!=null)return;job=kind;token=UUID.randomUUID().toString();error="";render();observe();}
    private void observe(){if(!resumed||token==null||draft==null)return;TravelPlan copy=draft.copy();TravelCuePlan savedCues=cues;TravelPlans.Repository repo=repository;String kind=job;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{if(kind.equals("save")){repo.save(copy,savedCues,TravelReminders.clock.getAsLong());TravelCues.changed();try{TripSleepRuntime.reconcile(app);}catch(RuntimeException unavailable){new TripSleepStore(app).error("Trip saved. Review the travel sleep reminder schedule.");}}try{TravelReminders.apply(app);return null;}catch(Exception failure){return failure.getMessage();}});if(!operation.done){handler.postDelayed(poll,75);return;}PlanOperations.forget(token);token=null;if(operation.error!=null){error=operation.error;render();return;}if(kind.equals("save")){draft=repository.load(TravelReminders.clock.getAsLong());cues=new TravelCueStore(repository.prefs).load(draft,TravelReminders.clock.getAsLong());}if(operation.notice!=null){error="Plan saved. Reminders need attention: "+operation.notice;render();return;}error="";if(kind.equals("save")){setResult(RESULT_OK);finish();}else render();}
    private void show(String value){error=value==null?"Travel settings need attention.":value;if(problem!=null){problem.setText(error);problem.setVisibility(View.VISIBLE);problem.post(()->problem.requestRectangleOnScreen(new android.graphics.Rect(0,0,problem.getWidth(),problem.getHeight()),true));}}
    private void back(){if(token!=null)return;if(route.equals("cue-date")){route="cues";render();}else if(route.equals("cues")){try{if(!cueBefore.isEmpty())cues=TravelCueJson.decode(new org.json.JSONObject(cueBefore));}catch(Exception failure){show("The window could not be restored. Reopen this page.");return;}cueBefore="";route=cueParent;render();}else if(route.equals("reminders")){route="planning";render();}else if(!route.isEmpty()){route="";render();}else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override public void finish(){if(token==null)super.finish();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft==null)return;rememberScroll();Bundle positions=new Bundle();for(Map.Entry<String,Integer> entry:scrolls.entrySet())positions.putInt(entry.getKey(),entry.getValue());state.putBundle("routeScrolls",positions);state.putString("cueParent",cueParent);state.putString("pickerKind",pickerKind);state.putString("cues",TravelCueJson.encode(cues).toString());state.putString("cueBefore",cueBefore);state.putString("cueError",cueError);state.putString("home",draft.home);state.putString("destination",draft.destination);state.putString("departure",draft.departure.toString());state.putInt("minute",draft.minute);state.putInt("days",draft.days);state.putBoolean("reminders",draft.reminders);state.putBoolean("trackingReminders",draft.trackingReminders);state.putLong("revision",draft.revision);state.putString("route",route);state.putString("month",month.toString());state.putString("query",query);state.putInt("zoneLimit",zoneLimit);state.putString("error",error);state.putString("token",token);state.putString("job",job);state.putBoolean("permissionSave",permissionSave);if(dialog!=null&&dialog.isShowing())state.putBundle("picker",dialog.onSaveInstanceState());}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();if(Build.VERSION.SDK_INT>=33&&backCallback!=null)getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(backCallback);super.onDestroy();}
